H('416.d.2.B',4,"A project engineer who prepares calculations and drawings reports progress to the:","project manager",["competing firm","news reporter","vendor's cashier"],"Team members report up to the manager.")
H('416.d.2.C',3,"Software that tracks tasks, deadlines, and costs for a construction job is a project:","management tool",["music player","photo filter","recipe book"],"Tools help track progress.")
